/* ───────── mảnh HTML dùng lại (giống khuôn tập 2, đã kiểm chứng) ───────── */
const LOP = (sau, inner, style) => `<div class="lop" data-sau="${sau}"${style?` style="${style}"`:""}>${inner||""}</div>`;
/* MỌI lớp của khối này nới -14% như lớp .ov của trang, nên hệ toạ độ svg nới theo */
const VB14 = "-179.2 -100.8 1638.4 921.6";
